Item.method_code:
if (!window.isEditMode) {
	return { hidden: true };
}

const { commandFactory } = options;
const itemNode = window.item;
const saveCommand = commandFactory('SaveItem', { itemNode });
const state = options.getState();
const disabled = state.isInvalidForm || !saveCommand.canExecute();
return {
	hidden: false,
	disabled
};
